CREATE TABLE portfolios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, country VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, asset_type VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE holdings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, portfolio_id BIGINT NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE, symbol VARCHAR(20) NOT NULL, instrument_name VARCHAR(160) NOT NULL, quantity DECIMAL(24,8) NOT NULL, average_cost DECIMAL(20,6) NOT NULL, market_value DECIMAL(20,6), currency VARCHAR(3) NOT NULL, UNIQUE(portfolio_id,symbol));
CREATE SEQUENCE watchlists_id_seq START WITH 1;
CREATE TABLE watchlists_usa (id BIGINT DEFAULT NEXT VALUE FOR watchlists_id_seq PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, name VARCHAR(40) NOT NULL, market VARCHAR(10) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlists_india (id BIGINT DEFAULT NEXT VALUE FOR watchlists_id_seq PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, name VARCHAR(40) NOT NULL, market VARCHAR(10) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlist_items_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, watchlist_id BIGINT NOT NULL REFERENCES watchlists_usa(id) ON DELETE CASCADE, symbol VARCHAR(15) NOT NULL, name VARCHAR(160) NOT NULL, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(watchlist_id,symbol));
CREATE TABLE watchlist_items_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, watchlist_id BIGINT NOT NULL REFERENCES watchlists_india(id) ON DELETE CASCADE, symbol VARCHAR(15) NOT NULL, name VARCHAR(160) NOT NULL, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(watchlist_id,symbol));
CREATE TABLE watchlist_column_preferences (user_id BIGINT NOT NULL, column_key VARCHAR(50) NOT NULL, display_order INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_watchlist_column_preferences PRIMARY KEY (user_id, column_key), CONSTRAINT uq_watchlist_column_preferences_order UNIQUE (user_id, display_order), CONSTRAINT ck_watchlist_column_preferences_order CHECK (display_order >= 1));
CREATE INDEX idx_watchlist_column_preferences_user_id ON watchlist_column_preferences(user_id);
CREATE TABLE portfolio_entries_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'US', currency VARCHAR(3) NOT NULL DEFAULT 'USD', entry_month DATE NOT NULL, asset_type VARCHAR(40) NOT NULL, sub_asset_type_id BIGINT, invested_amount NUMERIC(20,2) NOT NULL, current_value NUMERIC(20,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_entries_usa UNIQUE NULLS NOT DISTINCT (user_id, entry_month, asset_type, sub_asset_type_id), CONSTRAINT ck_portfolio_entries_usa_country CHECK (country = 'US'), CONSTRAINT ck_portfolio_entries_usa_currency CHECK (currency = 'USD'), CONSTRAINT ck_portfolio_entries_usa_month CHECK (EXTRACT(DAY FROM entry_month) = 1), CONSTRAINT ck_portfolio_entries_usa_amounts CHECK (invested_amount >= 0 AND current_value >= 0));
CREATE TABLE portfolio_entries_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'India', currency VARCHAR(3) NOT NULL DEFAULT 'INR', entry_month DATE NOT NULL, asset_type VARCHAR(40) NOT NULL, sub_asset_type_id BIGINT, invested_amount NUMERIC(20,2) NOT NULL, current_value NUMERIC(20,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_entries_india UNIQUE NULLS NOT DISTINCT (user_id, entry_month, asset_type, sub_asset_type_id), CONSTRAINT ck_portfolio_entries_india_country CHECK (country = 'India'), CONSTRAINT ck_portfolio_entries_india_currency CHECK (currency = 'INR'), CONSTRAINT ck_portfolio_entries_india_month CHECK (EXTRACT(DAY FROM entry_month) = 1), CONSTRAINT ck_portfolio_entries_india_amounts CHECK (invested_amount >= 0 AND current_value >= 0));
CREATE TABLE stock_holdings_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'US', currency VARCHAR(3) NOT NULL DEFAULT 'USD', symbol VARCHAR(20) NOT NULL, name VARCHAR(160) NOT NULL, asset_type VARCHAR(10) NOT NULL, quantity NUMERIC(24,8) NOT NULL, average_cost NUMERIC(20,6) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_stock_holdings_usa UNIQUE (user_id, symbol), CONSTRAINT ck_stock_holdings_usa_country CHECK (country = 'US'), CONSTRAINT ck_stock_holdings_usa_currency CHECK (currency = 'USD'), CONSTRAINT ck_stock_holdings_usa_asset_type CHECK (asset_type IN ('STOCK', 'ETF')), CONSTRAINT ck_stock_holdings_usa_amounts CHECK (quantity > 0 AND average_cost >= 0));
CREATE TABLE stock_holdings_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'India', currency VARCHAR(3) NOT NULL DEFAULT 'INR', symbol VARCHAR(20) NOT NULL, exchange VARCHAR(10) NOT NULL DEFAULT 'NSE', name VARCHAR(160) NOT NULL, asset_type VARCHAR(10) NOT NULL, quantity NUMERIC(24,8) NOT NULL, average_cost NUMERIC(20,6) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_stock_holdings_india UNIQUE (user_id, symbol, exchange), CONSTRAINT ck_stock_holdings_india_country CHECK (country = 'India'), CONSTRAINT ck_stock_holdings_india_currency CHECK (currency = 'INR'), CONSTRAINT ck_stock_holdings_india_exchange CHECK (exchange IN ('NSE', 'BSE')), CONSTRAINT ck_stock_holdings_india_asset_type CHECK (asset_type IN ('STOCK', 'ETF')), CONSTRAINT ck_stock_holdings_india_amounts CHECK (quantity > 0 AND average_cost >= 0));
CREATE TABLE portfolio_asset_types_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'US', code VARCHAR(40) NOT NULL, name VARCHAR(60) NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_asset_types_usa UNIQUE (user_id, code), CONSTRAINT uq_portfolio_asset_types_usa_owner UNIQUE (user_id, id), CONSTRAINT ck_portfolio_asset_types_usa_country CHECK (country = 'US'));
CREATE TABLE portfolio_asset_types_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'India', code VARCHAR(40) NOT NULL, name VARCHAR(60) NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_asset_types_india UNIQUE (user_id, code), CONSTRAINT uq_portfolio_asset_types_india_owner UNIQUE (user_id, id), CONSTRAINT ck_portfolio_asset_types_india_country CHECK (country = 'India'));
CREATE TABLE portfolio_sub_asset_types_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'US', asset_type_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(60) NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_sub_asset_types_usa UNIQUE (user_id, code), CONSTRAINT uq_portfolio_sub_asset_types_usa_owner UNIQUE (user_id, id), CONSTRAINT ck_portfolio_sub_asset_types_usa_country CHECK (country = 'US'), CONSTRAINT fk_portfolio_sub_asset_types_usa_asset_type FOREIGN KEY (user_id, asset_type_id) REFERENCES portfolio_asset_types_usa (user_id, id));
ALTER TABLE portfolio_entries_usa ADD CONSTRAINT fk_portfolio_entries_usa_sub_asset_type FOREIGN KEY (user_id, sub_asset_type_id) REFERENCES portfolio_sub_asset_types_usa (user_id, id);
CREATE TABLE portfolio_sub_asset_types_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, country VARCHAR(10) NOT NULL DEFAULT 'India', asset_type_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(60) NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_portfolio_sub_asset_types_india UNIQUE (user_id, code), CONSTRAINT uq_portfolio_sub_asset_types_india_owner UNIQUE (user_id, id), CONSTRAINT ck_portfolio_sub_asset_types_india_country CHECK (country = 'India'), CONSTRAINT fk_portfolio_sub_asset_types_india_asset_type FOREIGN KEY (user_id, asset_type_id) REFERENCES portfolio_asset_types_india (user_id, id));
ALTER TABLE portfolio_entries_india ADD CONSTRAINT fk_portfolio_entries_india_sub_asset_type FOREIGN KEY (user_id, sub_asset_type_id) REFERENCES portfolio_sub_asset_types_india (user_id, id);
